-- Pet Zoo base setup (shard DB): tables + BigRadius setting + rooms
CREATE TABLE IF NOT EXISTS aceclassic_shard.zoo_setting (`key` VARCHAR(64) NOT NULL PRIMARY KEY, `value` VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS aceclassic_shard.zoo_room (name VARCHAR(64) NOT NULL PRIMARY KEY, radius FLOAT NOT NULL);
CREATE TABLE IF NOT EXISTS aceclassic_shard.zoo_room_point (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, room VARCHAR(64) NOT NULL, cell INT UNSIGNED NOT NULL, x FLOAT NOT NULL, y FLOAT NOT NULL, z FLOAT NOT NULL, qz FLOAT NOT NULL, qw FLOAT NOT NULL);
CREATE TABLE IF NOT EXISTS aceclassic_shard.zoo_animal (wcid INT UNSIGNED NOT NULL PRIMARY KEY, shell_wcid INT UNSIGNED NOT NULL, donor VARCHAR(64) NOT NULL, donated_at DOUBLE NOT NULL, obj_desc TEXT NULL, room VARCHAR(64) NOT NULL, wake_on_approach TINYINT(1) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS aceclassic_shard.zoo_reward (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, player VARCHAR(64) NOT NULL, wcid INT UNSIGNED NOT NULL, monster VARCHAR(128) NOT NULL, for_donation VARCHAR(128) NULL, given_at DOUBLE NOT NULL, egg_guid INT UNSIGNED NOT NULL);
CREATE TABLE IF NOT EXISTS aceclassic_shard.zoo_blocked (wcid INT UNSIGNED NOT NULL PRIMARY KEY);
